<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {LocalSocialStore,SocialError,type PublicBuilding} from './social';
import {neighbor} from '../town/copy';
const props=defineProps<{family:string;token?:string}>();const emit=defineEmits<{close:[];town:[focus?:string]}>();
const social=new LocalSocialStore(),friends=ref<PublicBuilding[]>([]),pending=ref<Array<{id:string;expiresAt:string}>>([]),link=ref(''),message=ref(''),busy=ref(false),confirm=ref('');
const copy=neighbor;
async function refresh(){friends.value=await social.neighbors(props.family);pending.value=await social.invites(props.family);}
function explain(e:unknown){message.value=e instanceof SocialError?e.reason==='own_family'?copy.ownFamily:e.reason==='neighbor_full'?copy.fullAccept:copy.tokenInvalid:copy.tryLater;}
async function create(){busy.value=true;try{const i=await social.createInvite(props.family);link.value=i.link;await refresh();}catch(e){explain(e);}finally{busy.value=false;}}
async function cancel(id:string){try{await social.cancelInvite(props.family,id);link.value='';await refresh();}catch(e){explain(e);}}
async function accept(){busy.value=true;try{const id=await social.accept(props.family,props.token??'');history.replaceState(null,'','/app/world');emit('town',id);}catch(e){explain(e);}finally{busy.value=false;}}
async function unlink(id:string){try{await social.unlink(props.family,id);confirm.value='';await refresh();message.value='친구 관계를 끝냈어요';}catch(e){explain(e);}}
onMounted(()=>{void refresh().catch(explain);});
</script>
<template><div class="w-social-overlay" role="dialog" aria-modal="true" aria-label="친구"><section class="g-panel w-social-card"><header><h2>{{token?copy.acceptTitle:copy.sectionTitle}}</h2><button class="g-btn" type="button" @click="emit('close')">닫기</button></header><p>{{copy.accept2}}</p><template v-if="token"><p>{{copy.accept3}}</p><button class="g-btn g-btn--primary" type="button" :disabled="busy" @click="accept">{{copy.acceptGo}}</button></template><template v-else><button class="g-btn" type="button" :disabled="busy" @click="create">친구 초대 링크 만들기</button><label v-if="link">{{copy.linkLabel}}<input class="w-link" readonly :value="link" @focus="($event.target as HTMLInputElement).select()" /></label><p>{{copy.hint}}</p><div v-for="i in pending" :key="i.id"><span>{{copy.expires(new Date(i.expiresAt).toLocaleDateString('ko-KR'))}}</span><button class="g-btn" type="button" @click="cancel(i.id)">{{copy.cancelInvite}}</button></div><p v-if="!friends.length">{{copy.none}}</p><ul><li v-for="f in friends" :key="f.id"><button class="g-btn" type="button" @click="emit('town',f.id)">{{f.child}}의 미술관</button><button class="g-btn" type="button" @click="confirm=f.id">{{copy.unlink}}</button><template v-if="confirm===f.id"><p>{{copy.unlinkConfirm}}</p><button class="g-btn" type="button" @click="unlink(f.id)">끊기</button><button class="g-btn" type="button" @click="confirm=''">그만두기</button></template></li></ul></template><p role="status">{{message}}</p></section></div></template>
<style scoped>.w-social-overlay{position:absolute;inset:0;z-index:25;background:#1c292a55;display:grid;place-items:center;padding:20px}.w-social-card{width:min(520px,100%);max-height:85vh;overflow:auto;padding:24px;display:grid;gap:14px}.w-social-card header{display:flex;justify-content:space-between;align-items:center}.w-social-card h2,.w-social-card p{margin:0}.w-social-card ul{list-style:none;padding:0;display:grid;gap:12px}.w-social-card li{display:flex;flex-wrap:wrap;gap:8px}.w-link{width:100%;min-height:44px;font:inherit;padding:8px;border:1px solid #b4aa8d;border-radius:8px}</style>
